    n -= static_cast<uint128_t>(d) << 64;
  }
  auto p = static_cast<uint128_t>(v) * static_cast<uint64_t>(n >> 64) + n;
  auto q = static_cast<uint64_t>(p >> 64) + 1;
  auto r = static_cast<uint64_t>(n) - q * d;
  if (r > static_cast<uint64_t>(p)) {
    --q;
    r += d;
  }
